using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Data;
using System.Drawing;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;
using System.IO;
using Jamera.Properties;
using DevExpress.Utils;

namespace Jamera.Messages
{
    public partial class Import_Phone : DevExpress.XtraEditors.XtraForm
    {
        public Single_Message singal_msg { get; set; }
        public Import_Phone()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
            string icon_path = Settings.Default.company_icon;
            string img_name = Settings.Default.db_name;
            if (icon_path != "")
            {
                FileInfo image = new FileInfo(icon_path);
                if (image.Exists == true)
                {
                    this.Icon = new Icon(icon_path);
                }
            }
            else
            {
                string img_path = Environment.CurrentDirectory + @"\Icons\" + img_name + @".ico";
                FileInfo image = new FileInfo(img_path);
                if (image.Exists == true)
                {
                    this.Icon = new Icon(img_path);
                }
            }
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void Import_Phone_KeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Escape)
            {
                //if (XtraMessageBox.Show("Are you sure, you want to cancel !", "Warning Alert", MessageBoxButtons.YesNo) != DialogResult.No)
                //{
                    this.Close();
                //}
            }
            else if (e.KeyCode == Keys.Enter && account_cmb.Text != "")
            {
                this.Select_Phone_No();
            }
        }

        public void Select_Phone_No()
        {
            //Here Will be parsing of cell phone numbers
            if(account_cmb.Text != "")
            {
                String Office_Phone = null;
                String Home_Phone = null;
                if (account_cmb.Properties.View.GetFocusedRowCellValue("Store.Code") != DBNull.Value)
                {
                    singal_msg.store_id =Convert.ToInt32(account_cmb.Properties.View.GetFocusedRowCellValue("Store.Code"));
                }
                singal_msg.account_id = Convert.ToInt32(account_cmb.Properties.View.GetFocusedRowCellValue("Code"));
                singal_msg.Group_Name = Convert.ToString(account_cmb.Properties.View.GetFocusedRowCellValue("Group"));
                if (account_cmb.Properties.View.GetFocusedRowCellValue("Office Phone") != DBNull.Value)
                {
                    Office_Phone = account_cmb.Properties.View.GetFocusedRowCellValue("Office Phone").ToString();
                    singal_msg.Office_Phone = Office_Phone;
                }
                if (account_cmb.Properties.View.GetFocusedRowCellValue("Home Phone") != DBNull.Value)
                {
                    Home_Phone = account_cmb.Properties.View.GetFocusedRowCellValue("Home Phone").ToString();
                    singal_msg.Home_Phone = Home_Phone;
                }
                if (account_cmb.Properties.View.GetFocusedRowCellValue("Name") != DBNull.Value)
                {
                    singal_msg.Name = account_cmb.Properties.View.GetFocusedRowCellValue("Name").ToString();
                }
                if (account_cmb.Properties.View.GetFocusedRowCellValue("Group") != DBNull.Value)
                {
                    singal_msg.Group_Name = account_cmb.Properties.View.GetFocusedRowCellValue("Group").ToString();
                }
                if (Home_Phone != null && Home_Phone != "" && Office_Phone != "" && Office_Phone != null)
                {
                    singal_msg.phone_inp.Text = Home_Phone + "," + Office_Phone;
                }else if(Home_Phone != null && Home_Phone != "")
                {
                    singal_msg.phone_inp.Text = Home_Phone;
                }
                else if (Office_Phone != "" && Office_Phone != null)
                {
                    singal_msg.phone_inp.Text = Office_Phone;
                }
                else
                {
                    singal_msg.phone_inp.Text = null;
                }
            }
            this.Close();
        }

        private void Import_Phone_Load(object sender, EventArgs e)
        {
            this.Size = new Size(account_cmb.Size.Width, account_cmb.Size.Height);
            this.Location = new Point(this.Location.X, this.Location.Y - 100);
            account_cmb.Properties.PopupFormSize = new Size(account_cmb.Width - 5,350);
        }

        private void Import_Phone_Shown(object sender, EventArgs e)
        {
            account_cmb.Focus();
            account_cmb.ShowPopup();

        }

        private void select_btn_Click(object sender, EventArgs e)
        {
            Select_Phone_No();
        }

        private void cancel_btn_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void account_cmb_Properties_ButtonClick(object sender, DevExpress.XtraEditors.Controls.ButtonPressedEventArgs e)
        {
            int i = e.Button.Index;

            if(i == 1){
                if(account_cmb.Text != "")
                {
                    Select_Phone_No();
                }
                else
                {
                    account_cmb.ShowPopup();
                    account_cmb.Focus();
                }
            }else if (i == 2)
            {
                this.Close();
            }
        }

        private void account_cmb_EditValueChanged(object sender, EventArgs e)
        {
           
        }
    }
}